import{_ as e,o,c as a,a2 as r}from"./chunks/framework.BEUshCVJ.js";const p=JSON.parse('{"title":"Keyboard shortcuts","description":"","frontmatter":{},"headers":[],"relativePath":"guide/shortcuts.md","filePath":"guide/shortcuts.md","lastUpdated":1792976573000}'),s={name:"guide/shortcuts.md"};function h(c,t,d,n,i,l){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h1><p>This page lists MeetCue&#39;s global shortcuts and shows how to change them. The shortcuts work while your meeting app has focus.</p><h2 id="default-shortcuts" tabindex="-1">Default shortcuts <a class="header-anchor" href="#default-shortcuts" aria-label="Permalink to &quot;Default shortcuts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+Alt+Space</code></td><td>Start or pause listening</td></tr><tr><td><code>Ctrl+Alt+H</code></td><td>Panel: full → mini bar → hidden</td></tr><tr><td><code>Ctrl+Alt+[</code></td><td>Previous question</td></tr><tr><td><code>Ctrl+Alt+]</code></td><td>Next question (in practice: skip the question)</td></tr><tr><td><code>Ctrl+Alt+Enter</code></td><td>Mark the current question answered</td></tr></tbody></table><h2 id="why-these-keys" tabindex="-1">Why these keys <a class="header-anchor" href="#why-these-keys" aria-label="Permalink to &quot;Why these keys&quot;">​</a></h2><p>The defaults avoid shortcuts that are already common on Windows laptops:</p><ul><li>meeting apps that use <code>Ctrl+Shift</code> combinations, such as mute in Teams;</li><li>input methods that use <code>Ctrl+Space</code> or <code>Shift+Space</code>;</li><li>graphics drivers that rotate the screen with <code>Ctrl+Alt</code> plus an arrow key;</li><li>chat apps that use <code>Ctrl+Alt+A</code>, <code>Ctrl+Alt+W</code> or <code>Ctrl+Alt+Z</code>;</li><li>function keys, which act as media keys on many laptops.</li></ul><h2 id="change-a-shortcut" tabindex="-1">Change a shortcut <a class="header-anchor" href="#change-a-shortcut" aria-label="Permalink to &quot;Change a shortcut&quot;">​</a></h2><ol><li>Open <strong>Settings › Shortcuts</strong>.</li><li>Click <strong>Change</strong> next to the action.</li><li>Press the new key combination. Press <code>Esc</code> to cancel.</li></ol><p>If another program already uses the combination, the row turns red with <a href="/meetcue/troubleshooting/error-codes#mc-hk-001">MC-HK-001</a>. Choose a different combination. <strong>Restore defaults</strong> brings back the table above.</p><h2 id="when-shortcuts-don-t-reach-meetcue" tabindex="-1">When shortcuts don&#39;t reach MeetCue <a class="header-anchor" href="#when-shortcuts-don-t-reach-meetcue" aria-label="Permalink to &quot;When shortcuts don&#39;t reach MeetCue&quot;">​</a></h2><p>Windows doesn&#39;t deliver shortcuts to MeetCue while the foreground window is a program running as administrator, or a game in exclusive full screen. See <a href="/meetcue/troubleshooting/panel">Shortcuts and the panel</a>.</p>',12)])])}const m=e(s,[["render",h]]);export{p as __pageData,m as default};
